{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type v} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R),\n  F.totalDegree ≤ m →\n    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "ChevalleyThm.MvPolynomialC.numBound",
      "module_name": "Mathlib.RingTheory.Spectrum.Prime.ChevalleyComplexity",
      "kind": "definition",
      "type": "ℕ → (ℕ → ℕ) → ℕ → ℕ"
    },
    {
      "name": "Polynomial.card_mahlerMeasure_le_prod",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (B : NNReal),\n  {p | p.natDegree ≤ n ∧ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure ≤ ↑B}.ncard ≤\n    ∏ i, (2 * ⌊↑(n.choose ↑i) * B⌋₊ + 1)"
    },
    {
      "name": "ChevalleyThm.MvPolynomialC.degBound_le_degBound",
      "module_name": "Mathlib.RingTheory.Spectrum.Prime.ChevalleyComplexity",
      "kind": "theorem",
      "type": "∀ {k₁ k₂ : ℕ} {D₁ D₂ : ℕ → ℕ},\n  k₁ ≤ k₂ →\n    ∀ (n : ℕ),\n      (∀ i < n, D₁ i ≤ D₂ i) → ChevalleyThm.MvPolynomialC.degBound k₁ D₁ n ≤ ChevalleyThm.MvPolynomialC.degBound k₂ D₂ n"
    },
    {
      "name": "Polynomial.natDegree_sum_le_of_forall_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type w} (s : Finset ι) {S : Type u_1} [inst : Semiring S] {n : ℕ} (f : ι → Polynomial S),\n  (∀ i ∈ s, (f i).natDegree ≤ n) → (∑ i ∈ s, f i).natDegree ≤ n"
    },
    {
      "name": "Polynomial.finite_mahlerMeasure_le",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (B : NNReal), {p | p.natDegree ≤ n ∧ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure ≤ ↑B}.Finite"
    },
    {
      "name": "MvPolynomial.restrictDegree",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "definition",
      "type": "(σ : Type u) → (R : Type v) → [inst : CommSemiring R] → ℕ → Submodule R (MvPolynomial σ R)"
    }
  ]
}
